const PROJECT_PATTERN = /\.mf-bazis(?:\s*\(\d+\))?\.json$/i;

function fail(message) {
  UI.dialogs.ErrorBox('Martin Forest\n\n' + message);
  throw new Error(message);
}

function info(message) {
  UI.dialogs.MessageBox('Martin Forest\n\n' + message);
}

function candidateDownloadDirs() {
  const dirs = [], seen = new Set();
  const add = value => {
    if (!value) return;
    const full = path.resolve(value), key = full.toLowerCase();
    if (!seen.has(key)) { dirs.push(full); seen.add(key); }
  };
  if (EXPORT_FOLDER) { add(EXPORT_FOLDER); return dirs; }
  const env = process.env;
  const profile = env.USERPROFILE || (env.HOMEDRIVE && env.HOMEPATH ? env.HOMEDRIVE + env.HOMEPATH : '');
  for (const root of [profile, env.OneDrive, env.OneDriveConsumer, env.OneDriveCommercial]) {
    if (!root) continue;
    add(path.join(root, 'Downloads'));
    add(path.join(root, 'Загрузки'));
  }
  return dirs;
}
function newestProjectFile() {
  const candidates = [];
  for (const dir of candidateDownloadDirs()) {
    let names;
    try { names = fs.readdirSync(dir); } catch (_) { continue; }
    for (const name of names) {
      // Strict suffix excludes .notes-evidence.json, temporary downloads and sidecars.
      if (!PROJECT_PATTERN.test(name)) continue;
      const filename = path.join(dir, name);
      try {
        const stat = fs.statSync(filename);
        if (stat.isFile()) candidates.push({ filename, modified: Number(stat.mtimeMs) || 0 });
      } catch (_) {}
    }
  }
  candidates.sort((a,b) => b.modified - a.modified || a.filename.localeCompare(b.filename));
  return candidates.length ? candidates[0].filename : '';
}
function loadProjectFile() {
  let filename = newestProjectFile();
  const automatic = Boolean(filename);
  if (!filename) filename = UI.dialogs.RunOpenFileDialog({
    extensions: ['json'], initialDir: candidateDownloadDirs()[0] || '',
    title: 'Martin Forest — экспорт в Загрузках не найден; выберите *.mf-bazis.json'
  });
  if (!filename) return null;
  let payload;
  try {
    const before = fs.statSync(filename);
    payload = JSON.parse(fs.readFileSync(filename, 'utf8').replace(/^\uFEFF/, ''));
    const after = fs.statSync(filename);
    if (before.size !== after.size || before.mtimeMs !== after.mtimeMs) {
      throw new Error('Файл изменился во время чтения. Дождитесь завершения загрузки и запустите скрипт ещё раз.');
    }
  } catch (error) {
    // Never silently skip a damaged newest export and import an older project.
    throw new Error('Не удалось прочитать выбранный экспорт:\n' + filename + '\n' + error.message);
  }
  if (!payload || payload.format !== 'martin-forest-bazis-native-v2' ||
      !Array.isArray(payload.items) || !payload.items.length) {
    throw new Error('Неподдерживаемый или пустой экспорт: ' + filename);
  }
  for (const item of payload.items) {
    if (!item || typeof item !== 'object') throw new Error('Некорректный модуль в JSON.');
  }
  return { filename, payload, automatic };
}

function libraryRoot() {
  if (!fs.existsSync(LIBRARY_ROOT)) fail('Не найдена библиотека Martin Forest:\n' + LIBRARY_ROOT);
  return LIBRARY_ROOT;
}

function normalizeSourceName(filename) {
  const ext = path.extname(filename || '').toLowerCase();
  let stem = path.basename(filename || '', ext);
  // Windows/browser duplicate downloads commonly become "name (1).fr3d"
  // or "name.(1).fr3d". Treat those as the same donor identity.
  stem = stem.replace(/[\s.]*\(\d+\)$/u, '');
  stem = stem.replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
  return stem + ext;
}

function collectSourceFiles(root) {
  const files = [];
  const stack = [root];
  const seen = new Set();
  const maxDirectories = 10000;
  let truncated = false;

  while (stack.length) {
    if (seen.size >= maxDirectories) { truncated = true; break; }
    const dir = stack.pop();
    let real = dir;
    try { real = fs.realpathSync(dir); } catch (_) {}
    const key = String(real).toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);

    let entries = [];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (_) { continue; }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        stack.push(full);
        continue;
      }
      if (!entry.isFile()) continue;
      if (path.extname(entry.name).toLowerCase() !== '.fr3d') continue;
      files.push(full);
    }
  }

  return { files, directories: seen.size, truncated };
}

function sha256File(filename) {
  if (!crypto) return '';
  try {
    const h = crypto.createHash('sha256');
    h.update(fs.readFileSync(filename));
    return h.digest('hex').toLowerCase();
  } catch (_) {
    return '';
  }
}

