function nativeFrameProfile(item) {
  return NATIVE_FRAME_PROFILES[String(item.source_sha256 || '').toLowerCase()] || { rearInsetMm: 0 };
}

function nativeDimensions(dimensions, profile) {
  return { width:Number(dimensions.width), height:Number(dimensions.height),
    depth:Number(dimensions.depth) + profile.rearInsetMm };
}

function sceneFrame(nativeFrame, profile) {
  return {
    min: {x:nativeFrame.min.x, y:nativeFrame.min.y, z:nativeFrame.min.z + profile.rearInsetMm},
    size: {x:nativeFrame.size.x, y:nativeFrame.size.y, z:nativeFrame.size.z - profile.rearInsetMm}
  };
}

function vector(value, label) {
  const out = {};
  for (const axis of ['x', 'y', 'z']) {
    if (!value || !Number.isFinite(Number(value[axis]))) throw new Error('Нет координаты ' + label + '.' + axis);
    out[axis] = Number(value[axis]);
  }
  return out;
}

function readFrame(list) {
  const min = vector(elasticTransformation.GetObjectMinLocalPoint(list), 'frame.min');
  const size = vector(getLocalSize(list), 'frame.size');
  if (size.x <= 0 || size.y <= 0 || size.z <= 0) throw new Error('Некорректная габаритная рамка FR3D');
  return { min, size };
}

function rotateScene(v, degrees) {
  const a = degrees * Math.PI / 180, c = Math.cos(a), s = Math.sin(a);
  return { x: v.x*c - v.z*s, y: v.y, z: v.x*s + v.z*c };
}

function distance(a, b) {
  return Math.hypot(a.x-b.x, a.y-b.y, a.z-b.z);
}

function placeByFrame(obj, frame, item, log) {
  const desired = vector(item.position, 'position');
  const angle = Number(item.rotation || 0);
  if (!Number.isFinite(angle)) throw new Error('Некорректный угол поворота');
  // This anchor includes empty installation allowances (corner: left 50 mm),
  // excludes protruding fronts/handles, and preserves floor/upper elevation.
  const anchor = {
    x: frame.min.x + frame.size.x/2,
    y: frame.min.y,
    z: frame.min.z + frame.size.z/2
  };
  obj.SetDefaultTransform();
  if (angle) objectTransformation.RotateObject(obj, {x:0, y:1, z:0}, -angle, true);
  // Read the actual transform, so placement is independent of API pivot choice.
  const rotatedAnchor = vector(obj.ToGlobal(anchor), 'rotatedAnchor');
  const origin = vector(obj.ToGlobal({x:0, y:0, z:0}), 'origin');
  setObjectPosition(obj, {
    x: desired.x - (rotatedAnchor.x-origin.x),
    y: desired.y - (rotatedAnchor.y-origin.y),
    z: desired.z - (rotatedAnchor.z-origin.z)
  });
  const actual = vector(obj.ToGlobal(anchor), 'actualAnchor');
  const error = distance(actual, desired);
  if (error > PLACEMENT_TOLERANCE_MM) throw new Error('Ошибка привязки ' + error.toFixed(3) + ' мм');
  const finalOrigin = vector(obj.ToGlobal({x:0,y:0,z:0}), 'finalOrigin');
  for (const unit of [{x:100,y:0,z:0}, {x:0,y:100,z:0}, {x:0,y:0,z:100}]) {
    const measured = vector(obj.ToGlobal(unit), 'basis');
    const expected = rotateScene(unit, angle);
    const difference = distance({x:measured.x-finalOrigin.x,y:measured.y-finalOrigin.y,z:measured.z-finalOrigin.z}, expected);
    if (difference > PLACEMENT_TOLERANCE_MM) throw new Error('Поворот БАЗИС не совпал с экспортом: ' + angle + '°');
  }
  log.push('ПОЗИЦИЯ OK ' + item.name + ': центр низа=' + fmtSize(actual) +
    '; поворот сайта=' + angle + '°; ошибка=' + error.toFixed(3) + ' мм' +
    '; min рамки=' + fmtSize(frame.min));
}

function globalMinimum(obj) {
  // GabMin/GabMax are native GLOBAL bounds, including protruding fronts/fittings.
  // GMin/GMax are local bounds and must not be used as global coordinates.
  const min = vector(obj.GabMin, 'GabMin'), max = vector(obj.GabMax, 'GabMax');
  if (['x', 'y', 'z'].some(axis => min[axis] > max[axis]) || distance(min, max) === 0) {
    throw new Error('Некорректный габарит объекта: ' + obj.Name);
  }
  return min;
}

function globalLeftX(obj) { return globalMinimum(obj).x; }

function alignAssemblyX(objects, targetX, log) {
  return alignAssemblyXZ(objects, targetX, null, log);
}

function alignAssemblyXZ(objects, targetX, targetZ, log) {
  if (!Number.isFinite(targetX)) throw new Error('Некорректная координата левого края сборки');
  if (targetZ !== null && !Number.isFinite(targetZ)) throw new Error('Некорректная координата Z сборки');
  if (!objects.length) return { applied: false, targetX, targetZ, reason: 'Нет загруженных модулей' };
  const probes = [{x:0,y:0,z:0}, {x:100,y:0,z:0}, {x:0,y:100,z:0}, {x:0,y:0,z:100}];
  // Validate every object before moving any; preserve the native transform for rollback.
  const snapshots = objects.map(obj => {
    if (typeof obj.TranslateGCS !== 'function') throw new Error('БАЗИС не предоставил TranslateGCS');
    return { obj, minimum: globalMinimum(obj),
      position: vector({x:obj.PositionX,y:obj.PositionY,z:obj.PositionZ}, 'Position'),
      points: probes.map(p => vector(obj.ToGlobal(p), 'assembly.before')) };
  });
  const beforeX = Math.min(...snapshots.map(s => s.minimum.x));
  const beforeZ = Math.min(...snapshots.map(s => s.minimum.z));
  const shiftX = targetX - beforeX, shiftZ = targetZ === null ? 0 : targetZ - beforeZ;
  let afterX, afterZ;
  try {
    for (const s of snapshots) s.obj.TranslateGCS({x:shiftX,y:0,z:shiftZ});
    for (const s of snapshots) {
      for (let i = 0; i < probes.length; i++) {
        const actual = vector(s.obj.ToGlobal(probes[i]), 'assembly.after');
        const expected = {x:s.points[i].x+shiftX,y:s.points[i].y,z:s.points[i].z+shiftZ};
        if (distance(actual, expected) > PLACEMENT_TOLERANCE_MM) {
          throw new Error('Общий сдвиг изменил взаимное положение или поворот: ' + s.obj.Name);
        }
      }
    }
    afterX = Math.min(...objects.map(globalLeftX));
    afterZ = Math.min(...objects.map(obj => globalMinimum(obj).z));
    if (targetZ !== null && Math.abs(afterZ-targetZ) > PLACEMENT_TOLERANCE_MM) {
      throw new Error('Габарит сборки Z=' + afterZ.toFixed(3) + ', нужен ' + targetZ);
    }
    if (Math.abs(afterX-targetX) > PLACEMENT_TOLERANCE_MM) {
      throw new Error('Левый край сборки X=' + afterX.toFixed(3) + ', нужен ' + targetX);
    }
  } catch (error) {
    const rollbackErrors = [];
    for (const s of snapshots) {
      try { setObjectPosition(s.obj, s.position); }
      catch (rollbackError) { rollbackErrors.push(String(rollbackError.message || rollbackError)); }
    }
    throw new Error(String(error.message || error) + (rollbackErrors.length
      ? '; ОШИБКА ВОЗВРАТА: ' + rollbackErrors.join('; ') : '; общий сдвиг отменён'));
  }
  log.push('СБОРКА X/Z OK: X=' + afterX.toFixed(3) + '; Z=' + afterZ.toFixed(3) +
    ' мм; общий сдвиг X=' + shiftX.toFixed(3) + '; Z=' + shiftZ.toFixed(3) +
    ' мм; взаимное положение, высоты Y и повороты сохранены.');
  return { applied: true, targetX, targetZ, beforeX, beforeZ, afterX, afterZ, shiftX, shiftZ, objectCount: objects.length };
}


function normalizePanelName(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^a-zа-я0-9]+/giu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function materialNameForBazis(material) {
  if (!material) return '';
  let name = String(material.name || '').trim();
  const article = String(material.article || '').trim();
  if (!name && !article) return '';
  // Exact names from the user's original M1 catalogue rows 1501 and 1637.
  // BAZIS identity includes the complete name AND a separate article field.
  // Display normalization must not remove the article from the name or collapse
  // the double space in the original 890 PO name.
  const defaults = {
    '71118e45-0ce3-534b-ad68-db1238304f18': {article:'605 PO',name:'ЛДСП BYSPAN 18мм Белый 605 PO'},
    '389a2abc-c6e2-5214-a41b-60054320d0ff': {article:'890 PO',name:'ЛДСП BYSPAN 18мм  Персидский жемчуг 890 PO'}
  };
  const known = defaults[material.variant_id];
  if (known && article === known.article && Number(material.thickness) === 18 &&
      name.replace(/\s+/g,' ') === known.name.replace(/\s+/g,' ')) name = known.name;
  if (article) {
    // An already serialized native full name is idempotent; an article suffix
    // in ordinary catalogue text is part of the name and must be preserved.
    const native = name.split(/\r\n?|\n/);
    if (native.length === 2 && native[1].trim() === article) return native[0] + '\r' + article;
    return (name || article) + '\r' + article;
  }
  return name;
}

function firstMaterial(parts, predicate) {
  for (const part of parts || []) {
    if (!part || part.optical_material || !predicate(part)) continue;
    const material = part && part.material;
    if (material && (material.name || material.article)) return {
      name: material.name || '',
      article: material.article || '',
      variant_id: material.variant_id || '',
      material_id: material.material_id || '',
      thickness: Number(part.thickness) || 0
    };
  }
  return null;
}

