function readNotesForDisplay(result) {
  // The window displays native readback, never the JSON under a success heading.
  const lines = [], errors = [];
  const append = (obj, label, expectedCheck) => {
    try {
      const value = existingObjectNotes(obj);
      if (expectedCheck && expectedCheck.verified && normalizedNote(value) !== normalizedNote(expectedCheck.expected)) {
        throw new Error('Текст изменился после проверки импорта.');
      }
      if (hasNote(value)) lines.push(label, ...normalizedNote(value).split('\n'), '');
      else if (expectedCheck && expectedCheck.requested) throw new Error('Заметка объекта пуста.');
    } catch (error) {
      const message = label + ': ' + String(error.message || error);
      errors.push(message);
      lines.push(label, 'ОШИБКА ЧТЕНИЯ — ' + String(error.message || error), '');
    }
  };
  const checks = result.noteChecks || [];
  append(currentFileData.model, 'ОБЩАЯ МОДЕЛЬ', checks.find(c => c.itemIndex == null));
  const list = asList(currentFileData.model), count = Number(list.Count);
  let visibleModuleIndex = 0;
  if (!Number.isInteger(count) || count < 0) errors.push('Не удалось прочитать список модулей.');
  else for (let i = 0; i < count; i++) {
    const obj = childAt(list, i);
    if (isServiceFrame(obj)) continue;
    visibleModuleIndex++;
    const check = checks.find(c => c.itemIndex != null && c.objectIndex === i);
    append(obj, 'МОДУЛЬ ' + (check ? check.itemIndex + 1 : visibleModuleIndex) + ': ' + (obj ? String(obj.Name || 'Без названия') : 'Объект недоступен'), check);
  }
  if (!lines.length) lines.push('В импортированной модели нет заметок.');
  return { lines, errors };
}
function showNotesWindow(summaryLines, noteLines) {
  const lines = [...summaryLines, '', 'ЗАМЕТКИ, ПРОЧИТАННЫЕ ИЗ БАЗИС', '', ...noteLines];
  let form = null;
  try {
    if (!UI.components || typeof UI.components.NewForm !== 'function' ||
        typeof UI.components.NewListBox !== 'function' || typeof UI.components.NewButton !== 'function' ||
        typeof execution === 'undefined' || typeof execution.ContinueExecution !== 'function' ||
        typeof execution.FinishExecution !== 'function') {
      throw new Error('Компоненты формы недоступны в этой версии API.');
    }
    form = UI.components.NewForm();
    form.Caption = 'Martin Forest — Заметки';
    form.Width = 960; form.Height = 680; form.Left = 60; form.Top = 40;
    const close = UI.components.NewButton(form, form);
    close.Caption = 'Закрыть заметки'; close.Height = 38; close.Align = UI.constants.align.bottom;
    const list = UI.components.NewListBox(form, form);
    list.Align = UI.constants.align.client;
    list.Sorted = false;
    list.ScrollWidth = lines.reduce((width, line) => Math.max(width, String(line).length * 10), 900);
    for (const line of lines) list.Items.Add(String(line));
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      execution.FinishExecution();
    };
    close.OnClick = () => { form.Visible = false; finish(); };
    form.OnClose = () => { finish(); };
    form.Show();
    execution.ContinueExecution();
    return 'form';
  } catch (error) {
    if (form) { try { form.Visible = false; } catch (_) {} }
    console.log('Окно заметок: используется резервный диалог. ' + String(error.message || error));
    // If custom forms are unsupported, still show all text automatically in bounded pages.
    const pages = []; let page = [];
    for (const originalLine of lines) {
      const value = String(originalLine);
      const segments = value.match(/.{1,110}/gu) || [''];
      for (const segment of segments) {
        page.push(segment);
        if (page.length === 24) { pages.push(page.join('\n')); page = []; }
      }
    }
    if (page.length) pages.push(page.join('\n'));
    for (let i = 0; i < pages.length; i++) {
      UI.dialogs.MessageBox('Martin Forest — Заметки (' + (i + 1) + '/' + pages.length + ')\n\n' + pages[i]);
    }
    return 'message';
  }
}
(function main() {
  let notesFilename = '';
  try {
    const project = loadProjectFile();
    if (!project) return;
    const runId = new Date().toISOString().replace(/[:.]/g, '-') + '-' + Math.random().toString(16).slice(2, 10);
    // Fail closed BEFORE API probing, donor discovery or any model changes.
    const brief = projectBrief(project.payload);
    notesFilename = saveHandoffText(project.filename, brief, runId);
    assertEmptyTestModel();
    const root = libraryRoot();
    const prepared = prepareProject(project.payload, root);
    // The empty model is already open. Do not call NewModel, which discards unsaved work.
    const result = importProject(prepared, root, project.payload);
    result.selectedExport = project.filename;
    result.exportSelection = project.automatic ? 'LATEST_DOWNLOAD' : 'FILE_DIALOG_FALLBACK';
    const display = readNotesForDisplay(result);
    for (const error of display.errors) result.log.push('ОШИБКА ЧТЕНИЯ ОКНА ЗАМЕТОК: ' + error);
    let logFilename = '', evidenceError = '';
    try { logFilename = saveImportLog(project.filename, result, runId); }
    catch (e) { evidenceError = 'ОШИБКА СОХРАНЕНИЯ ДИАГНОСТИКИ: ' + e.message; result.log.push(evidenceError); }
    for (const line of result.log) console.log(line);
    const hasErrors = result.failed || result.materialErrors || result.assemblyPlacement.error || evidenceError || display.errors.length || result.notesVerified < result.notesRequested;
    const lines = [hasErrors ? 'ИМПОРТ С ОШИБКАМИ — см. диагностику ниже.' : 'Импорт выполнен. Заметки показаны ниже.',
      'Версия: ' + IMPORT_VERSION, 'Экспорт: ' + project.filename,
      'Выбор файла: ' + (project.automatic ? 'автоматически — последний в Загрузках' : 'вручную — в Загрузках экспорт не найден'),
      'Загружено модулей: ' + result.loaded + '/' + project.payload.items.length + '; ошибок загрузки: ' + result.failed,
      result.assemblyPlacement.applied ? 'Левый габарит всей сборки: X=' + result.assemblyPlacement.afterX.toFixed(3) + ' мм; минимальный Z=' + result.assemblyPlacement.afterZ.toFixed(3) + ' мм.' :
        'Привязка сборки по X/Z НЕ ВЫПОЛНЕНА: ' + (result.assemblyPlacement.error || result.assemblyPlacement.reason),
      'Ошибок назначения материала: ' + result.materialErrors,
      'Материалы прочитаны после Commit: ' + result.materialChecks.filter(c => c.verified).length + '/' + result.materialChecks.length + ' панелей.',
      'Заметки через GetObjectNotes после Commit: ' + result.notesVerified + '/' + result.notesRequested,
      'Общая заметка: ' + (result.modelNotesVerified ? 'ПРОЧИТАНА В ПАМЯТИ' : brief ? 'НЕ ПОДТВЕРЖДЕНА' : 'НЕТ В JSON'),
      'Сохранение и повторное открытие .b3d: НЕ ПРОВЕРЕНО.',
      'Просмотр заметок. Для редактирования: «Изделие → Заметки». Сохраните модель как .b3d.',
      notesFilename ? 'Текстовая копия: ' + notesFilename : 'В JSON нет производственных заметок.',
      logFilename ? 'Диагностика: ' + logFilename : 'Диагностика файлами НЕ ПОДТВЕРЖДЕНА.'];
    lines.push(...result.log.filter(line => /ОШИБКА|ВНИМАНИЕ/.test(line)));
    if (hasErrors) UI.dialogs.ErrorBox('Martin Forest\n\n' + lines.join('\n'));
    showNotesWindow(lines, display.lines);
  } catch (e) {
    console.log(e && e.stack ? e.stack : String(e));
    UI.dialogs.ErrorBox('Martin Forest ' + IMPORT_VERSION + '\n\n' + (e.message || String(e)) +
      '\n' + (notesFilename ? 'Текстовая копия задания: ' + notesFilename :
        'Текстовая копия задания НЕ СОЗДАНА. Исходный JSON не изменён.') +
      '\nСохранность заметок в B3D НЕ ПОДТВЕРЖДЕНА.');
  }
})();
